/**
 * 聊天相关数据模型
 * 包含会话、消息等所有相关模型
 */
import { BaseResponseData } from './base-models';

/**
 * 搜索模式枚举
 */
export enum SearchModeEnum {
    /** 禁用搜索 */
    OFF = 'off',
    /** 自动决定是否搜索 */
    AUTO = 'auto',
    /** 强制启用搜索 */
    ON = 'on'
}

/**
 * 搜索数据源类型枚举
 */
export enum SearchSourceTypeEnum {
    /** 网页搜索 */
    WEB = 'web',
    /** X(Twitter)搜索 */
    X = 'x',
    /** 新闻搜索 */
    NEWS = 'news',
    /** RSS订阅 */
    RSS = 'rss'
}

/**
 * 搜索数据源配置
 */
export interface SearchSourceConfig {
    /** 数据源类型 */
    type: SearchSourceTypeEnum;
    /** 是否启用该数据源 */
    enabled?: boolean;
}

/**
 * 搜索参数配置
 */
export interface SearchParameters {
    /** 搜索模式 */
    mode?: SearchModeEnum;
    /** 是否返回引用信息 */
    return_citations?: boolean;
    /** 最大搜索结果数量，范围1-50 */
    max_search_results?: number;
    /** 搜索开始日期，格式YYYY-MM-DD */
    from_date?: string;
    /** 搜索结束日期，格式YYYY-MM-DD */
    to_date?: string;
    /** 数据源配置列表 */
    sources?: SearchSourceConfig[];
}

/**
 * 会话信息
 */
export class SessionInfo extends BaseResponseData {
    /** 会话ID */
    id: number;
    /** 会话标题 */
    title: string;
    /** 会话唯一标识符，用于分享 */
    session_id: string;
    /** 是否置顶 */
    is_pinned: boolean;
    /** 创建时间 */
    created_at: string;
    /** 最后消息时间 */
    last_message_time?: string;
}

/**
 * 会话响应信息
 */
export class SessionResponseInfo extends BaseResponseData {
    /** 会话ID */
    id: number;
    /** 会话标题 */
    title: string;
    /** 会话唯一标识符，用于分享 */
    session_id: string;
    /** 是否置顶 */
    is_pinned: boolean;
    /** 创建时间 */
    created_at: string;
    /** 最后消息时间 */
    last_message_time?: string;
}

/**
 * 会话列表响应信息
 */
export class ChatHistoryResponseInfo extends BaseResponseData {
    /** 会话列表 */
    items: SessionInfo[];
    /** 是否有更多数据 */
    has_more: boolean;
}

/**
 * 消息信息
 */
export class MessageInfo extends BaseResponseData {
    /** 消息ID */
    id: number;
    /** 会话ID */
    session_id: number;
    /** 消息内容 */
    content: string;
    /** 消息类型 */
    message_type: string;
    /** 引用消息ID */
    reference_id?: number;
    /** 消息角色 (user/assistant) */
    role: string;
    /** 创建时间 */
    created_at: string;
    /** 推理内容，仅当启用推理功能时有值 */
    reasoning_content?: string;
    /** 搜索引用链接列表，仅当使用搜索功能时有值 */
    search_citations?: string[];
}

/**
 * 消息发送响应信息
 */
export class MessageSendResponseInfo extends BaseResponseData {
    /** 消息ID */
    id: number;
    /** 会话ID */
    session_id: number;
    /** 消息内容 */
    content: string;
    /** 消息类型 */
    message_type: string;
    /** 引用消息ID */
    reference_id?: number;
    /** 消息角色 (user/assistant) */
    role: string;
    /** 创建时间 */
    created_at: string;
    /** 推理内容，仅当启用推理功能时有值 */
    reasoning_content?: string;
    /** 搜索引用链接列表，仅当使用搜索功能时有值 */
    search_citations?: string[];
}

/**
 * 消息列表响应信息
 */
export class MessageListResponseInfo extends BaseResponseData {
    /** 消息列表 */
    items: MessageInfo[];
    /** 是否有更多数据 */
    has_more: boolean;
}

/**
 * 流式消息回调数据
 */
export interface StreamMessageData {
    /** 当前消息片段内容 */
    content: string;
    /** 累积的完整内容 */
    full_content?: string;
    /** 是否为文本消息 */
    is_text?: boolean;
    /** 解析错误标识 */
    parse_error?: boolean;
    /** 搜索引用链接列表 */
    citations?: string[];
}

/**
 * 流式消息结束回调数据
 */
export interface StreamEndData {
    /** 完整的消息内容 */
    content: string;
}

/**
 * 流式请求控制器
 */
export interface StreamController {
    /** 关闭流式连接 */
    close: () => void;
}

/**
 * 会话更新参数
 */
export interface SessionUpdateParams {
    /** 会话ID */
    id: number;
    /** 更新内容 */
    update: {
        /** 会话标题 */
        title?: string;
        /** 是否置顶 */
        is_pinned?: boolean;
    };
}

/**
 * 消息发送参数
 */
export interface MessageSendParams {
    /** 会话ID，如果不提供，系统会自动创建新会话 */
    session_id?: number | null;
    /** 消息内容 */
    content: string;
    /** 消息类型，默认为'text' */
    message_type?: string;
    /** 引用消息ID */
    reference_id?: number | null;
    /** 使用的AI模型（必填） */
    model: string | number;
    /** 是否启用推理功能（仅XMIND-G-3-MINI和XMIND-G-3-MINI-FAST模型支持） */
    reasoning?: boolean | null;
    /** 是否使用流式响应模式返回AI回复 */
    streaming?: boolean | null;
    /** 是否启用实时搜索功能 */
    enable_search?: boolean | null;
}

/**
 * 流式消息回调函数类型
 */
export type StreamMessageCallback = (data: StreamMessageData) => void;

/**
 * 流式错误回调函数类型
 */
export type StreamErrorCallback = (error: Error) => void;

/**
 * 流式结束回调函数类型
 */
export type StreamEndCallback = (data: StreamEndData) => void; 